export type EstadoMateria = 'aprobada' | 'cursando' | 'desaprobada' | 'disponible' | 'proxima';

export class Materia {
  constructor(
    public codigo: string,
    public nombre: string,
    public cargaHoraria: number,
    public correlativas: Materia[] = [],
    public anio: number = 0,
    public estado: EstadoMateria = 'disponible',
  ) {}

  getCorrelativas(): Materia[] {
    return this.correlativas;
  }

  estaDisponible(aprobadas: Materia[]): boolean {
    const codigosAprobados = aprobadas.map(m => m.codigo);
    return this.correlativas.every(c => codigosAprobados.includes(c.codigo));
  }
}
